import{_ as s,a0 as a,w as i,s as g,ao as l,I as p,x as e,a1 as n,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"遷移LVM分區到新的邏輯卷/驅動器（第六部分） | LCTT x X-CMD","titleTemplate":false,"description":"遷移LVM分區到新的邏輯卷/驅動器（第六部分） | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"遷移LVM分區到新的邏輯卷/驅動器（第六部分） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"遷移LVM分區到新的邏輯卷/驅動器（第六部分） | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141013 Migrating LVM Partitions to New Logical Volume (Drive)--Part VI","title":"遷移LVM分區到新的邏輯卷/驅動器（第六部分）","tag":"201412","desc":""},"relativePath":"201412/20141013 Migrating LVM Partitions to New Logical Volume (Drive)--Part VI.md","filePath":"[post].md"}'),m={name:"201412/20141013 Migrating LVM Partitions to New Logical Volume (Drive)--Part VI.md"};function d(c,t,v,h,w,u){const o=a("Link");return i(),g("div",null,[t[13]||(t[13]=l(`<h1 id="遷移lvm分區到新的邏輯卷-驅動器-第六部分" tabindex="-1">遷移LVM分區到新的邏輯卷/驅動器（第六部分） <a class="header-anchor" href="#遷移lvm分區到新的邏輯卷-驅動器-第六部分" aria-label="Permalink to “遷移LVM分區到新的邏輯卷/驅動器（第六部分）”">​</a></h1><p>這是我們正在進行的LVM系列的第六部分。在本文中，我們將為大家展示怎樣在線將現存的邏輯卷遷移到其它新的驅動器。在開始之前，我想要先來介紹一下LVM遷移及其特性。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/LVM-Migrations.png" alt="LVM Storage Migration"></p><p><em>LVM存儲遷移</em></p><h3 id="什麼是lvm遷移" tabindex="-1">什麼是LVM遷移？ <a class="header-anchor" href="#什麼是lvm遷移" aria-label="Permalink to “什麼是LVM遷移？”">​</a></h3><p><strong>LVM</strong>遷移是LVM眾多優秀特性之一，通過它，我們可以遷移邏輯捲到一個新的磁盤而不會丟失數據，也不用關機操作。該特性的功能是將數據從舊磁盤移動到新磁盤。通常，我們只是在一些磁盤發生錯誤時，才將數據從一個磁盤遷移到另外一個磁盤存儲。</p><h3 id="遷移特性" tabindex="-1">遷移特性 <a class="header-anchor" href="#遷移特性" aria-label="Permalink to “遷移特性”">​</a></h3><ul><li>將邏輯卷從一個磁盤移動到另一個磁盤。</li><li>我們可以使用任何類型的磁盤，如SATA、SSD、SAS、SAN storage iSCSI或者FC。</li><li>在線遷移磁盤，而且數據不會丟失。</li></ul><p>在LVM遷移中，我們將交換各個卷、文件系統以及位於已有的存儲中的數據。例如，如果我們有一個單一邏輯卷，它已經映射到了物理卷，而該物理卷是一個物理硬盤驅動器。</p><p>現在，如果我們需要升級服務器存儲為SSD硬盤驅動器，我們首先需要考慮什麼？重新格式化磁盤？不！我們不必重新格式化服務器，LVM可以選擇將這些舊的SATA驅動器上的數據遷移到新的SSD驅動器上。在線遷移將會支持任何類型的磁盤，不管是本地驅動器，還是SAN或者光纖通道都可以。</p><h4 id="我的服務器設置" tabindex="-1">我的服務器設置 <a class="header-anchor" href="#我的服務器設置" aria-label="Permalink to “我的服務器設置”">​</a></h4><pre><code>操作系統：	 CentOS 6.5 Final
IP地址：	  192.168.0.224
系統主機名：	lvmmig.tecmintlocal.com
</code></pre><h3 id="步驟1-檢查當前驅動器" tabindex="-1">步驟1： 檢查當前驅動器 <a class="header-anchor" href="#步驟1-檢查當前驅動器" aria-label="Permalink to “步驟1： 檢查當前驅動器”">​</a></h3><p><strong>1.</strong>假設我們已經有一個名為“<strong>vdb</strong>”的虛擬驅動器，它已經被映射到了其中一個邏輯卷“<strong>tecmint_lv</strong>”。現在，我們想要遷移“<strong>vdb</strong>”這個邏輯捲到其它某個新的存儲設備中。在開始之前，首先在下面所示的<strong>fdisk</strong>和lvs命令的幫助下驗證該虛擬驅動器。</p><pre><code># fdisk -l | grep vd
# lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-Logical-Volume-Disk.png" alt="Check Logical Volume Disk"></p><p><em>檢查邏輯卷磁盤</em></p><h3 id="步驟2-檢查新添加的驅動器" tabindex="-1">步驟2： 檢查新添加的驅動器 <a class="header-anchor" href="#步驟2-檢查新添加的驅動器" aria-label="Permalink to “步驟2： 檢查新添加的驅動器”">​</a></h3><p><strong>2.</strong>在我們確認了現存驅動器後，現在是時候來將新的SSD驅動器連接到系統並在fdisk命令的幫助下驗證新添加的驅動器了。</p><pre><code># fdisk -l | grep dev
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-New-Added-Drive.png" alt="Check New Added Drive"></p><p><em>檢查新添加的驅動器</em></p><p><strong>注意</strong>：你看到上面屏幕中的內容了嗎？新的驅動器已經被成功添加了，其名稱為“<strong>/dev/sda</strong>”。</p><h3 id="步驟3-檢查當前邏輯和物理卷" tabindex="-1">步驟3： 檢查當前邏輯和物理卷 <a class="header-anchor" href="#步驟3-檢查當前邏輯和物理卷" aria-label="Permalink to “步驟3： 檢查當前邏輯和物理卷”">​</a></h3><p><strong>3.</strong>現在，讓我們開始創建物理卷、卷組和邏輯卷以用於遷移。在創建卷時，確保檢查<strong>/mnt/lvm</strong>掛載點下的當前邏輯卷的數據。用以下命令來列出掛載點並檢查數據。</p><pre><code># df -h
# cd /mnt/lvm
# cat tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-Logical-Volume-Data.png" alt="Check Logical Volume Data"></p><p><em>檢查邏輯卷數據</em></p><p><strong>注意</strong>：出於演示的目的，我們已經在<strong>/mnt/lvm</strong>掛載點下創建了兩個文件，我們將在線將這些數據遷移到新的驅動器中。</p><p><strong>4.</strong>在遷移之前，確保對確認與物理卷相關的邏輯卷和卷組名稱，並且確認哪個物理卷用於容納該卷組和邏輯卷。</p><pre><code># lvs
# vgs -o+devices | grep tecmint_vg
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Confirm-Logical-Volume-Names.png" alt="Confirm Logical Volume Names"></p><p><em>確認邏輯卷名稱</em></p><p><strong>注意</strong>：看到上面屏幕中的內容了嗎？“<strong>vdb</strong>”容納了卷組<strong>tecmint_vg</strong>。</p><h3 id="步驟4-創建新物理卷" tabindex="-1">步驟4： 創建新物理卷 <a class="header-anchor" href="#步驟4-創建新物理卷" aria-label="Permalink to “步驟4： 創建新物理卷”">​</a></h3><p><strong>5.</strong>在在我們新添加的SSD驅動器中創建物理卷之前，我們需要使用fdisk來定義分區。在創建分區時，別忘了修改分區類型為LVM（8e）。</p><pre><code># pvcreate /dev/sda1 -v
# pvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-Physical-Volume.png" alt="Create Physical Volume"></p><p><em>創建物理卷</em></p><p><strong>6.</strong>接下來，使用‘vgextend命令’來添加新創建的物理捲到現存卷組tecmint_vg。</p><pre><code># vgextend tecmint_vg /dev/sda1
# vgs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Add-Physical-Volume.png" alt="Add Physical Volume"></p><p><em>添加物理卷</em></p><p><strong>7.</strong>要獲得卷組的完整信息列表，請使用‘vgdisplay’命令。</p><pre><code># vgdisplay tecmint_vg -v
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/List-Volume-Group-Info.png" alt="List Volume Group Info"></p><p><em>列出卷組信息</em></p><p><strong>注意</strong>：在上面屏幕中，我們可以看到在輸出結果的結束處，我們的PV已經添加到了卷組中。</p><p><strong>8.</strong>如果我們需要知道更多關於哪些設備被映射的信息，請使用‘<strong>dmsetup</strong>’依賴命令。</p><pre><code># lvs -o+devices
# dmsetup deps /dev/tecmint_vg/tecmint_lv
</code></pre><p>在上面的結果中，有個<strong>1個</strong>依賴（PV）或（驅動器），而這裏<strong>17</strong>被列出了。如果你想要檢查設備，那些關聯的有着主、次設備號的驅動器，以確認，使用下面的命令。</p><pre><code># ls -l /dev | grep vd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/List-Device-Information.png" alt="List Device Information"></p><p><em>列出設備信息</em></p><p><strong>注意</strong>：在上面的命令中，我們可以看到主設備號是<strong>252</strong>，次設備號是<strong>17</strong>，它連接到了<strong>vdb1</strong>。希望你理解了上面命令的輸出。</p><h3 id="步驟5-lvm鏡像法" tabindex="-1">步驟5： LVM鏡像法 <a class="header-anchor" href="#步驟5-lvm鏡像法" aria-label="Permalink to “步驟5： LVM鏡像法”">​</a></h3><p><strong>9.</strong>現在，該使用鏡像法來進行遷移了。使用‘<strong>lvconvert</strong>’命令來將數據從舊邏輯卷遷移到新驅動器。</p><pre><code># lvconvert -m 1 /dev/tecmint_vg/tecmint_lv /dev/sda1
</code></pre><ul><li><strong>-m</strong> = 鏡像</li><li><strong>1</strong> = 添加單個鏡像</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Mirroring-Method-Migration.png" alt="Mirroring Method Migration"></p><p><em>鏡像法遷移</em></p><p><strong>注意</strong>：上面的遷移過程根據卷的大小會花費一段時間。</p><p><strong>10.</strong>在遷移過程完成後，驗證轉換的鏡像。</p><pre><code># lvs -o+devices
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Verify-Converted-Mirror.png" alt="Verify Converted Mirror"></p><p><em>驗證轉換的鏡像</em></p><p><strong>11.</strong>當你確認轉換的鏡像沒有任何問題後，你可以移除舊的虛擬磁盤<strong>vdb1</strong>。<strong>-m</strong>選項將移除鏡像，先前我們使用<strong>l</strong>來添加鏡像。</p><pre><code># lvconvert -m 0 /dev/tecmint_vg/tecmint_lv /dev/vdb1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Remove-Virtual-Disk.png" alt="Remove Virtual Disk"></p><p><em>移除虛擬磁盤</em></p><p><strong>12.</strong>在舊虛擬磁盤移除後，你可以使用以下命令來再次檢查邏輯卷設備。</p><pre><code># lvs -o+devices
# dmsetup deps /dev/tecmint_vg/tecmint_lv
# ls -l /dev | grep sd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-New-Mirrored-Device.png" alt="Check New Mirrored Device"></p><p><em>檢查新鏡像的設備</em></p><p>在上面的圖片中，你看到了嗎？我們的邏輯卷現在依賴於<strong>8,1</strong>，名稱為<strong>sda1</strong>。這説明我們的遷移過程已經完成了。</p><p><strong>13.</strong>現在驗證我們從舊驅動器上遷移過來的文件。如果在新驅動器中的數據與原數據一樣，那就説明我們每一步都完成得很完美。</p><pre><code># cd /mnt/lvm/
# cat tecmin.txt 
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-Mirrored-Data.png" alt="Check Mirrored Data"></p><p><em>檢查鏡像的數據</em></p><pre><code># vgreduce /dev/tecmint_vg /dev/vdb1
# vgs -o+devices
</code></pre><p><strong>14.</strong>在所有的都被完美創建後，現在該從卷組中刪除<strong>vdb1</strong>並進行再次確認，哪些設備依賴於我們的卷組。</p><p><strong>15.</strong>在從卷組<strong>tecmint_vg</strong>移除vdb1後，我們的邏輯卷還在那兒，因為我們已經將它從<strong>vdb1</strong>遷移到了<strong>sda1</strong>。</p><pre><code># lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Delete-Virtual-Disk.png" alt="Delete Virtual Disk"></p><p><em>刪除虛擬磁盤</em></p><h3 id="步驟6-lvm-pvmove鏡像法" tabindex="-1">步驟6： LVM pvmove鏡像法 <a class="header-anchor" href="#步驟6-lvm-pvmove鏡像法" aria-label="Permalink to “步驟6： LVM pvmove鏡像法”">​</a></h3><p><strong>16.</strong>我們可以使用帶有‘<strong>-n</strong>’（邏輯卷名稱）選項的‘<strong>pvmove</strong>’命令來取代‘<strong>lvconvert</strong>’鏡像命令，在兩個設備間進行數據鏡像。</p><pre><code># pvmove -n /dev/tecmint_vg/tecmint_lv /dev/vdb1 /dev/sda1
</code></pre><p>該命令是在兩個設備間鏡像數據的最簡單的一個，但是在真實環境中，<strong>鏡像</strong>比<strong>pvmove</strong>使用得更為頻繁。</p><h3 id="結尾" tabindex="-1">結尾 <a class="header-anchor" href="#結尾" aria-label="Permalink to “結尾”">​</a></h3><p>在本文中，我們介紹了怎樣將邏輯卷從一個驅動器遷移到另一個驅動器。希望你已經掌握了邏輯卷管理中這一新的技巧。對於該配置，必須建立在掌握邏輯卷管理基礎技能的基礎上。對於基礎配置，請參閲本文頂部需求章節中提供的鏈接。</p><hr>`,92)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),n(o,{href:"http://www.tecmint.com/lvm-storage-migration/#comment-331336"},{default:r(()=>[...t[0]||(t[0]=[e("http://www.tecmint.com/lvm-storage-migration/#comment-331336",-1)])]),_:1})]),p("p",null,[t[5]||(t[5]=e("作者：",-1)),n(o,{href:"http://www.tecmint.com/author/babinlonston/"},{default:r(()=>[...t[2]||(t[2]=[e("Babin Lonston",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),n(o,{href:"https://github.com/GOLinux"},{default:r(()=>[...t[3]||(t[3]=[e("GOLinux",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:r(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[10]||(t[10]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),n(o,{href:"http://linux.cn/"},{default:r(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const f=s(m,[["render",d]]);export{M as __pageData,f as default};
